// ── Opções do filtro de raio (distância) ────────────────────────────────────
// Compartilhadas pelos dois lados (prestador vê vagas / anunciante vê prestadores)
// pra ficarem idênticas. Infinity = "Qualquer distância" (sem corte de raio):
// como distKm(d) <= Infinity é sempre true, o sentinela dispensa caso especial
// no filtro e mantém o fail-open (quem não tem geo cai em distKm === Infinity).
const OPCOES_RAIO_KM: { v: number; lab: string }[] = [
  { v: 5,        lab: "até 5 km"   },
  { v: 20,       lab: "até 20 km"  },
  { v: 50,       lab: "até 50 km"  },
  { v: 100,      lab: "até 100 km" },
  { v: Infinity, lab: "Qualquer distância" },
];

// ── Wrapper pra disparar push notification via Edge Function send-push ──────
type PushTipo = "mensagem" | "vaga_proxima" | "candidatura" | "selecionado" | "confirmacao" | "convite_resposta" | "desistencia" | "default";
// Notificação persistida no histórico (sininho). `destino` = tela ao tocar.
type NotifItem = { tipo: "ok" | "erro"; msg: string; ts: number; lida?: boolean; destino?: string };
type DiaristaInfoCandidatura = {
  nome?: string;
  funcao?: string;
  foto_url?: string;
  lat?: number | null;
  lng?: number | null;
  geo_preciso?: boolean | null;
  categorias?: string[];
  carta?: string;
  curriculo_path?: string;
  valor_proposta?: number;
  observacao_proposta?: string;
};
type CandidaturaLocal = {
  id: string;
  diaria_id: string;
  diarista_id: string;
  status: string;
  diarista_info?: DiaristaInfoCandidatura | null;
};
async function enviarPush(
  userIds: string[],
  title: string,
  body: string,
  opts: { tipo?: PushTipo; url?: string } = {},
) {
  if (!userIds.length) return;
  try {
    const { data: { session: sess } } = await supabase.auth.getSession();
    await fetch(`${SUPABASE_URL}/functions/v1/send-push`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "apikey": SUPABASE_ANON_KEY,
        "Authorization": `Bearer ${sess?.access_token ?? SUPABASE_ANON_KEY}`,
      },
      body: JSON.stringify({
        user_ids: userIds, title, body,
        tipo: opts.tipo || "default",
        url: opts.url || "/",
      }),
    });
  } catch { /* push é best-effort — falhas não interrompem o fluxo */ }
}
